    "context": "Jeú executa com brutalidade calculada o extermínio de toda a descendência de Acabe em Jezreel e Samaria, e depois engana os adoradores de Baal reunindo-os todos num falso festival para matá-los e destruir o templo do deus estrangeiro. Apesar desse zelo reconhecido por Deus, Jeú não remove os bezerros de ouro em Betel e Dã, mantendo a idolatria estrutural que Jeroboão havia instituído gerações antes.",
