          "text": "Então Jeú escreveu-lhes uma segunda carta que dizia: \"Se vocês estão do meu lado e estão dispostos a obedecer-me, tragam-me as cabeças dos descendentes de seu senhor a Jezreel, amanhã a esta hora\". Os setenta descendentes de Acabe estavam sendo criados pelas autoridades da cidade."
