          "n": 19,
          "text": "Por isso convoquem todos os profetas de Baal, todos os seus ministros e todos os seus sacerdotes. Ninguém deverá faltar, pois oferecerei um grande sacrifício a Baal. Quem não vier, morrerá\". Mas Jeú estava agindo traiçoeiramente, a fim de exterminar os ministros de Baal."
